import { getHostName } from "./diagnostics.js";
function isCommentNode(node) {
    return node.nodeType === Node.COMMENT_NODE;
}
/** @internal */
export function collectHydrationRepeatRanges(first, location, markers) {
    const itemRanges = [];
    const stack = [];
    let current = first;
    while (current !== null && current !== location) {
        if (isCommentNode(current)) {
            const data = current.data;
            if (markers.isRepeatViewStartMarker(data)) {
                stack.push(current);
            }
            else if (markers.isRepeatViewEndMarker(data)) {
                const startMarker = stack.pop();
                if (startMarker === undefined) {
                    const expected = current.previousSibling === null
                        ? "end should never be null."
                        : "repeat start marker not found.";
                    throw new Error(`Error when hydrating inside "${getHostName(location)}": ${expected}`);
                }
                if (stack.length === 0) {
                    const start = startMarker.nextSibling;
                    const end = current.previousSibling;
                    itemRanges.push({
                        start,
                        end: end === startMarker ? start : end,
                        startMarker,
                        endMarker: current,
                    });
                }
            }
        }
        current = current.nextSibling;
    }
    if (stack.length !== 0) {
        throw new Error(`Error when hydrating inside "${getHostName(location)}": repeat end marker not found.`);
    }
    return itemRanges;
}
